const output = $json.output;

let parsed;

try {
  parsed = typeof output === "string"
    ? JSON.parse(output)
    : output;
} catch (error) {
  throw new Error("AI Agent returned invalid JSON: " + output);
}

// Get original Gmail data
const email = $('Get a message').first().json;

// Get sender and subject directly from Gmail output
const from = email.From || "Unknown sender";
const subject = email.Subject || "No subject";

return [
  {
    json: {
      from: from,
      subject: subject,
      priority: parsed.priority || "Low",
      reason: parsed.reason || "No reason provided",
      action_required: parsed.action_required || "No",
      suggested_action: parsed.suggested_action || "No action required"
    }
  }
];

